<script setup>import { reactive, ref } from "vue"; import { useRouter } from "vue-router"; import { useAuthStore } from "../../stores/auth"; import AuthLayout from "../../layouts/AuthLayout.vue"; const form = reactive({ email: "", mot_de_passe: "" }); const error = ref(""); const loading = ref(false); const auth = useAuthStore(); const router = useRouter(); const submit = async () => { error.value = ""; loading.value = true; try { await auth.login(form); router.push(auth.isAdmin ? "/admin" : "/catalogue"); } catch (exception) { error.value = exception.message; } finally { loading.value = false; } };</script><template><AuthLayout><h1 class="mt-8 text-3xl font-bold text-slate-800">Connexion</h1><p class="mt-2 text-sm text-slate-500">Accédez à votre espace de gestion.</p><form class="mt-7 space-y-4" @submit.prevent="submit"><label class="form-control"><span class="label-text">Adresse e-mail</span><input v-model="form.email" type="email" class="input input-bordered" required></label><label class="form-control"><span class="label-text">Mot de passe</span><input v-model="form.mot_de_passe" type="password" class="input input-bordered" required></label><p v-if="error" class="text-sm text-error">{{ error }}</p><button class="btn w-full border-0 bg-[#17482d] text-white hover:bg-[#0e3520]" :disabled="loading">{{ loading ? 'Connexion…' : 'Se connecter' }}</button></form><p class="mt-6 text-center text-sm">Pas encore de compte ? <RouterLink class="font-semibold text-[#17482d]" to="/register">Créer un compte</RouterLink></p></AuthLayout></template>
